'use client';

import Link from 'next/link';
import { useEffect, useState, type FormEvent } from 'react';
import { Activity, ArrowRight, Bot, Building2, CalendarDays, Check, FileText, Mail, Phone, Plus, Search as SearchIcon, ShieldCheck, Sparkles, Users, X } from 'lucide-react';
import { results, type JsonRecord } from '@/services/jigsaw-service';
